    cfg = copy.deepcopy(BASE)
    for key, val in overrides.items():
        cfg[key] = val
    try:
        res = pci.solve(cfg)
    except (NotImplementedError, RuntimeError) as exc:
        print(f"{label:&lt;44s} FAILED: {str(exc)[:90]}")
        return None
    T = cfg["time"]["T"]
    errs = {p: 100.0 * (res.final(p) - TRUE[p]) / TRUE[p] for p in cfg["unknowns"]}
    x_rmse = np.mean([res.rmse([f"x{d}"], start=T / 2)[f"x{d}"] for d in range(1, 7)])
    worst = max(errs, key=lambda p: abs(errs[p]))
    print(f"{label:&lt;44s} {res.runtime:6.1f}s  mean x-RMSE {x_rmse:.2e}  max |param err| {abs(errs[worst]):5.2f}% ({worst})  "
          + "  ".join(f"{p}={errs[p]:+.1f}%" for p in errs))
    return res
